import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs['target_snapshot'].copy()
    cdc = inputs['cdc_events'].copy()
    watermark = inputs['watermark'].copy()

    # Determine high watermark timestamp
    if len(watermark) > 0:
        high_ts = watermark['high_ts'].iloc[0]
    else:
        high_ts = None

    # Filter events strictly after the watermark
    if high_ts is not None:
        events = cdc[cdc['event_ts'] > high_ts].copy()
    else:
        events = cdc.copy()

    # Apply events sequentially by (event_ts, event_seq), stable ordering
    events = events.sort_values(['event_ts', 'event_seq'], kind='mergesort')

    # Build initial state from target_snapshot (last row wins if duplicate user_id)
    state = {}
    for row in target.itertuples(index=False):
        state[row.user_id] = {
            'email': row.email,
            'status': row.status,
            'status_ts': row.status_ts,
        }

    seven_days = pd.Timedelta(days=7)

    for row in events.itertuples(index=False):
        uid = row.user_id
        op = row.op
        ts = row.event_ts
        email = row.email

        cur = state.get(uid)

        if op == 'D':
            if cur is None:
                # No prior record: deletion creates a row; no prior email to
                # preserve, fall back to the event's email value.
                state[uid] = {
                    'email': email,
                    'status': 'DELETED',
                    'status_ts': ts,
                }
            else:
                # Soft delete: email preserved as of deletion (i.e. the
                # email value already held, NOT the event's email field).
                state[uid] = {
                    'email': cur['email'],
                    'status': 'DELETED',
                    'status_ts': ts,
                }

        elif op == 'U':
            if cur is None or cur['status'] == 'ACTIVE':
                # Upsert for new user or active user
                state[uid] = {
                    'email': email,
                    'status': 'ACTIVE',
                    'status_ts': ts,
                }
            elif cur['status'] == 'DELETED':
                threshold = cur['status_ts'] + seven_days
                if ts > threshold:
                    # Resurrection: strictly more than 7 days after deletion
                    state[uid] = {
                        'email': email,
                        'status': 'ACTIVE',
                        'status_ts': ts,
                    }
                # else: discard, deletion remains sticky within the window
            # else: unknown status value, leave state unchanged defensively

    rows = []
    for uid, info in state.items():
        rows.append({
            'user_id': uid,
            'email': info['email'],
            'status': info['status'],
            'status_ts': info['status_ts'],
        })

    new_snapshot = pd.DataFrame(rows, columns=['user_id', 'email', 'status', 'status_ts'])

    return {'new_snapshot': new_snapshot}
